use std::collections::BTreeMap;

pub type AccountId = String;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Transfer {
    pub from: AccountId,
    pub to: AccountId,
    pub amount: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LedgerError {
    EmptyAccount,
    DuplicateAccount,
    UnknownAccount,
    SameAccount,
    ZeroAmount,
    InsufficientFunds,
    Overflow,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ledger {
    balances: BTreeMap<AccountId, u64>,
    supply: u64,
}

impl Ledger {
    pub fn new(origin: AccountId, supply: u64) -> Result<Self, LedgerError> {
        if origin.is_empty() {
            return Err(LedgerError::EmptyAccount);
        }
        let mut balances = BTreeMap::new();
        balances.insert(origin, supply);
        Ok(Self { balances, supply })
    }

    pub fn add_account(&mut self, id: AccountId) -> Result<(), LedgerError> {
        if id.is_empty() {
            return Err(LedgerError::EmptyAccount);
        }
        if self.balances.contains_key(&id) {
            return Err(LedgerError::DuplicateAccount);
        }
        self.balances.insert(id, 0);
        Ok(())
    }

    pub fn balance(&self, id: &str) -> Option<u64> {
        self.balances.get(id).copied()
    }

    pub fn total(&self) -> u64 {
        self.supply
    }

    pub fn apply(&mut self, transfer: &Transfer) -> Result<(), LedgerError> {
        if transfer.amount == 0 {
            return Err(LedgerError::ZeroAmount);
        }
        if transfer.from == transfer.to {
            return Err(LedgerError::SameAccount);
        }

        let from = self.balance(&transfer.from).ok_or(LedgerError::UnknownAccount)?;
        let to = self.balance(&transfer.to).ok_or(LedgerError::UnknownAccount)?;
        if from <= transfer.amount {
            return Err(LedgerError::InsufficientFunds);
        }

        let new_from = from
            .checked_sub(transfer.amount)
            .ok_or(LedgerError::InsufficientFunds)?;
        let new_to = to.checked_add(transfer.amount).ok_or(LedgerError::Overflow)?;
        if new_to == u64::MAX && to != u64::MAX {
            return Err(LedgerError::Overflow);
        }

        self.balances.insert(transfer.from.clone(), new_from);
        self.balances.insert(transfer.to.clone(), new_to);
        Ok(())
    }

    pub fn apply_batch(&mut self, transfers: &[Transfer]) -> Result<(), LedgerError> {
        let snapshot = self.balances.clone();
        for transfer in transfers {
            if let Err(error) = self.apply(transfer) {
                self.balances = snapshot;
                return Err(error);
            }
        }
        Ok(())
    }
}

