#[path = "solution.rs"]
mod solution;

use solution::{Ledger, LedgerError, Transfer};

fn transfer(from: &str, to: &str, amount: u64) -> Transfer {
    Transfer { from: from.to_string(), to: to.to_string(), amount }
}

#[test]
fn creates_origin_and_moves_credit_without_changing_total() {
    let mut ledger = Ledger::new("origin".to_string(), 100).expect("valid origin");
    ledger.add_account("alice".to_string()).expect("new account");
    assert_eq!(ledger.balance("origin").expect("origin exists"), 100);
    assert_eq!(ledger.balance("alice").expect("alice exists"), 0);
    assert_eq!(ledger.total(), 100);

    ledger.apply(&transfer("origin", "alice", 40)).expect("transfer");
    assert_eq!(ledger.balance("origin").unwrap(), 60);
    assert_eq!(ledger.balance("alice").unwrap(), 40);
    assert_eq!(ledger.total(), 100);
}

#[test]
fn validates_account_creation_atomically() {
    assert!(matches!(Ledger::new(String::new(), 0), Err(LedgerError::EmptyAccount)));
    let ledger = Ledger::new("zero".to_string(), 0).expect("zero supply allowed");
    assert_eq!(ledger.total(), 0);

    let mut ledger = Ledger::new("origin".to_string(), 7).unwrap();
    assert!(matches!(ledger.add_account(String::new()), Err(LedgerError::EmptyAccount)));
    assert!(matches!(ledger.add_account("origin".to_string()), Err(LedgerError::DuplicateAccount)));
    assert_eq!(ledger.total(), 7);
    assert_eq!(ledger.balance("origin").unwrap(), 7);
}

#[test]
fn failed_individual_transfers_leave_balances_unchanged() {
    let mut ledger = Ledger::new("a".to_string(), 10).unwrap();
    ledger.add_account("b".to_string()).unwrap();

    let cases = [
        transfer("missing", "b", 1),
        transfer("a", "missing", 1),
        transfer("a", "a", 1),
        transfer("a", "b", 0),
        transfer("a", "b", 11),
    ];
    for item in &cases {
        assert!(ledger.apply(item).is_err());
        assert_eq!(ledger.balance("a").unwrap(), 10);
        assert_eq!(ledger.balance("b").unwrap(), 0);
        assert_eq!(ledger.total(), 10);
    }
}

#[test]
fn batch_is_ordered_and_rolls_back_on_first_failure() {
    let mut ledger = Ledger::new("a".to_string(), 10).unwrap();
    ledger.add_account("b".to_string()).unwrap();
    ledger.add_account("c".to_string()).unwrap();
    let batch = [transfer("a", "b", 7), transfer("a", "c", 4)];

    assert!(matches!(ledger.apply_batch(&batch), Err(LedgerError::InsufficientFunds)));
    assert_eq!(ledger.balance("a").unwrap(), 10);
    assert_eq!(ledger.balance("b").unwrap(), 0);
    assert_eq!(ledger.balance("c").unwrap(), 0);
    assert_eq!(ledger.total(), 10);
}

#[test]
fn successful_and_empty_batches_preserve_supply() {
    let mut ledger = Ledger::new("a".to_string(), 20).unwrap();
    ledger.add_account("b".to_string()).unwrap();
    ledger.add_account("c".to_string()).unwrap();
    ledger.apply_batch(&[]).expect("empty batch succeeds");
    ledger.apply_batch(&[transfer("a", "b", 12), transfer("b", "c", 5)]).unwrap();
    assert_eq!(ledger.balance("a").unwrap(), 8);
    assert_eq!(ledger.balance("b").unwrap(), 7);
    assert_eq!(ledger.balance("c").unwrap(), 5);
    assert_eq!(ledger.total(), 20);
}

#[test]
fn destination_overflow_is_rejected_atomically() {
    let mut ledger = Ledger::new("rich".to_string(), u64::MAX).unwrap();
    ledger.add_account("sender".to_string()).unwrap();
    ledger.apply(&transfer("rich", "sender", 1)).unwrap();
    assert!(matches!(ledger.apply(&transfer("sender", "rich", 1)), Err(LedgerError::Overflow)));
    assert_eq!(ledger.balance("rich").unwrap(), u64::MAX - 1);
    assert_eq!(ledger.balance("sender").unwrap(), 1);
}

